import csv
from collections import defaultdict

def check_duplicates_and_format(csv_path):
    seen = defaultdict(set)
    duplicates = False
    with open(csv_path, newline='') as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            key = (row['city_id'], row['year'], row['indicator_id'])
            if key in seen[row['indicator_id']]:
                duplicates = True
                break
            else:
                seen[row['indicator_id']].add(key)
    if duplicates:
        print('Duplicates found')
    else:
        print('No duplicates found')

check_duplicates_and_format('outputs/t02_eurostat_raw.csv')

